import java.util.*;

public class Main {
    /** 模拟分代收集：对象在 Eden 分配，Minor GC 后幸存者进 Survivor 并随年龄晋升。 */
    static final int EDEN = 8, SURV = 2, OLD = 8, MAX_AGE = 3;

    static class Obj { int id, age; Obj(int id) { this.id = id; } }

    public static void main(String[] args) {
        List<Obj> eden = new ArrayList<>(), s0 = new ArrayList<>(), s1 = new ArrayList<>(), old = new ArrayList<>();
        int nextId = 1, minorGc = 0, promoted = 0;

        // 每一轮：分配若干对象，其中一部分是「朝生夕死」
        int[] allocPerRound = {6, 6, 6, 6};
        for (int round = 0; round < allocPerRound.length; round++) {
            for (int i = 0; i < allocPerRound[round] && eden.size() < EDEN; i++)
                eden.add(new Obj(nextId++));
            System.out.println("round " + (round + 1) + " alloc -> eden=" + eden.size());
            if (eden.size() < EDEN) continue;

            minorGc++;
            // Minor GC：Eden 中「编号为偶数」的对象幸存（模拟生命周期差异）
            List<Obj> survivors = new ArrayList<>();
            for (Obj o : eden) if (o.id % 2 == 0) survivors.add(o);
            eden.clear();
            // 上一次的 Survivor 也一起判定
            List<Obj> from = s0.isEmpty() ? s1 : s0;
            List<Obj> to = s0.isEmpty() ? s0 : s1;
            List<Obj> all = new ArrayList<>(from);
            all.addAll(survivors);
            from.clear();
            to.clear();
            for (Obj o : all) {
                o.age++;
                if (o.age >= MAX_AGE || to.size() >= SURV) { old.add(o); promoted++; }
                else to.add(o);
            }
            System.out.println("  MinorGC#" + minorGc + " survivors=" + all.size()
                    + " -> S(size=" + to.size() + ") Old(size=" + old.size() + ")");
        }
        System.out.println("=== summary ===");
        System.out.println("minor GCs        : " + minorGc);
        System.out.println("objects promoted : " + promoted);
        System.out.println("old gen size     : " + old.size());
        System.out.println("survivor halves used alternately : " + (s0.isEmpty() || s1.isEmpty()));
        System.out.println("key: survivor space is copied between halves, only one half is 'active'");
    }
}
